// Tool-only public component consumer. No authentication or simulated API response.
import {useRef,useState} from 'react';import ApplicationShell from '../components/application-shell';import {EditNavigationProvider} from '../components/elements/edit-navigation';import EditSession from '../components/elements/edit-session';import FormField from '../components/elements/form-field';import defaults from '../../../../shared/default-presentation.json';import type {Presentation} from '../../../../shared/presentation.mjs';import type {SaveResult} from '../../../../shared/editor.mjs';
const config:Presentation={...defaults,elements:{...defaults.elements,copy:{...defaults.elements.copy,emptyMode:'disable'}}};
export default function Page(){const pending=useRef<(()=>void)|null>(null),[commits,setCommits]=useState(0);return <EditNavigationProvider><ApplicationShell config={config} examples account={{id:'tool-component',name:'Synthetic component consumer',state:'active',kind:'person',roles:['user'],permissions:['application:read'],responsiblePersonId:null,authVersion:'1',heartbeatSeconds:30}}><h1>Navigation edit boundary fixture</h1><EditSession targetKey="controlled" title="Controlled editor" options={{initial:{name:'Initial'},normalize:v=>({...v}),validate:v=>v.name?{}:{name:'Required'},failureMessage:'Controlled failure',timeoutMs:300000}} fields={({editor,state})=><FormField label="Controlled value">{attrs=><input {...attrs} name="fixtureName" value={state.values.name} onChange={event=>editor.change('name',event.target.value)}/>}</FormField>} save={values=>new Promise<SaveResult<{name:string}>>(resolve=>{pending.current=()=>resolve({kind:'saved',values:{...values}});})} onCommit={()=>setCommits(n=>n+1)} onClose={()=>{}}/><button type="button" onClick={()=>pending.current?.()}>Resolve controlled save</button><output aria-label="commits">{commits}</output></ApplicationShell></EditNavigationProvider>;}
